import sys
sys.path.insert(0, '/work')
from solution import latest
import copy
a={'id':'b','timestamp':'2025-01-01T10:00:00+02:00','payload':1}
b={'id':'b','timestamp':'2025-01-01T08:30:00Z','payload':2}
c={'id':'a','timestamp':'2025-01-01T08:30:00+00:00','payload':3}
d={'id':'b','timestamp':'2025-01-01T03:30:00-05:00','payload':4}
data=[a,b,c,d]
before=copy.deepcopy(data)
assert latest(data)==[c,d]
assert data==before
assert latest([])==[]
try: latest([{'id':'a','timestamp':'2025-01-01T00:00:00','payload':0}])
except ValueError: pass
else: raise AssertionError('timezone required')

